/// <summary>
/// PaffH 11.01.25
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXBatchMultithreading, FormButtonTestCustomer), FormControlEventType::Clicked)
    , SuppressBPWarning('BPParameterNotUsed', 'Parameter required by the event interface.')]

public static void FormButtonTestCustomer_OnClicked(FormControl sender, FormControlEventArgs e)
{
    runAsync(classNum(NDXBatchMultithreading), 
        staticMethodStr(NDXBatchMultithreading, runNDXMultiThreadingCreateTaskController), 
        [true, NDXBatchProcessingParameters::find().SysOperationExecutionMode_CreateTaskService],
        System.Threading.CancellationToken::None, 
        classNum(NDXBatchMultithreading), 
        staticMethodStr(NDXBatchMultithreading, callBackrunNDXMultiThreadingCreateTaskController));
}

/// <summary>
/// PaffH 05.02.25
/// </summary>
/// <param name="sender">FormDataSource</param>
/// <param name="e">FormDataSourceEventArgs</param>
[FormDataSourceEventHandler(formDataSourceStr(NDXBatchMultithreading, NDXBatchProcessingTableHeader), FormDataSourceEventType::Activated)
    , SuppressBPWarning('BPParameterNotUsed', 'Parameter required by the event interface.')]
public static void NDXBatchProcessingTableHeader_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormRun formRun = sender.formRun();
    NDXBatchProcessingTableHeader nDXBatchProcessingTableHeader = sender.cursor();
    FormDataSource NDXBatchProcessingTable_DS;
    for (int i = 1; i <= 2; i++)
    {
        switch (i)
        {
            case 1:
                NDXBatchProcessingTable_DS = formRun.dataHelper().FindDataSource(formDataSourceStr(NDXBatchMultithreading, NDXBatchProcessingTable));
                break;
            case 2:
                NDXBatchProcessingTable_DS = formRun.dataHelper().FindDataSource(formDataSourceStr(NDXBatchMultithreading,NDXBatchProcessingTable_2));
                break;
        }
        switch (nDXBatchProcessingTableHeader.BatchProcessingType)
        {
            case NDXBatchProcessingType::SalesCurrentYear :
            case NDXBatchProcessingType::SalesLastYear :
                NDXBatchProcessingTable_DS.object(fieldNum(NDXBatchProcessingTable, ItemId)).visible(false);
                NDXBatchProcessingTable_DS.object(fieldNum(NDXBatchProcessingTable, RefTableId)).visible(false);
                NDXBatchProcessingTable_DS.object(fieldNum(NDXBatchProcessingTable, RefRecId)).visible(false);
                break;
        }
    }
}

/// <summary>
/// PaffH 17.03.25
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXBatchMultithreading, FormButtonSalesForm1Alliance), FormControlEventType::Clicked)
    , SuppressBPWarning('BPParameterNotUsed', 'Parameter required by the event interface.')]
public static void FormButtonSalesForm1Alliance_OnClicked(FormControl sender, FormControlEventArgs e)
{
    CustAccount alliance = '1001587';
    NDXUmsatzCSRefreshContract _contract = new NDXUmsatzCSRefreshContract();
    _contract.parmAlliance(alliance);
    _contract.parmumsatzCSRefreshType(NDXUmsatzCSRefreshType::Alliance);
    NDXUmsatzCSRefreshService nDXUmsatzCSRefreshService = new NDXUmsatzCSRefreshService();
    nDXUmsatzCSRefreshService.process(_contract);
}
